INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Einen Beitrag sperren', 'joomlaguide-locking-an-article-de', '<p>Wenn jemand einen Beitrag bearbeitet, <em>sperrt</em> Joomla ihn: Niemand sonst kann ihn gleichzeitig ändern. Wird der Beitrag gespeichert oder geschlossen, wird er wieder <em>freigegeben</em>.</p><p>Verlässt der Bearbeiter den Beitrag, ohne zu speichern oder zu schließen, bleibt er gesperrt. In dieser Tour siehst du, wie das passiert und wie ein Administrator ihn wieder freigibt.</p><p>Diese Tour folgt dem Tutorial <a href="https://guide.joomla.org/de/tutorials/inhaltsverwaltung/7-veroeffentlichung-zugriffsebene/7-5-einen-beitrag-sperren" target="_blank" rel="noopener">7.5 Einen Beitrag sperren</a> der Joomla-Benutzerdokumentation.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Inhalt', '<p>Klicke im Menü links auf <strong>Inhalt</strong>.</p><p>Es öffnet sich und zeigt, was du dort tun kannst.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Inhalt › Beiträge', '<p>Klicke unter <strong>Inhalt</strong> auf <strong>Beiträge</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Den Beitrag öffnen', '<p>Klicke auf <strong>Stadtrat genehmigt neues Verkehrsbudget</strong>, um ihn zu bearbeiten.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Stadtrat genehmigt neues Verkehrsbudget"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Verlassen, ohne zu schließen', '<p>Du bearbeitest jetzt den Beitrag. Klicke nicht auf <strong>Speichern</strong> oder <strong>Schließen</strong>, sondern auf die <em>Zurück</em>-Schaltfläche deines Browsers. So macht es ein Bearbeiter, der geht, ohne zu schließen.</p><p>Zurück in der Liste hat der Beitrag ein Schloss: Er ist gesperrt. Fahre mit der Maus über das Schloss, um zu sehen, wer ihn gesperrt hat und wann. (Kein Schloss? Lade die Seite neu.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Stadtrat genehmigt neues Verkehrsbudget"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Wer kann ihn bearbeiten?', '<p>Du hast den Beitrag gesperrt, also kannst du ihn noch öffnen. Andere Benutzer, selbst Administratoren, bekommen eine Fehlermeldung, wenn sie es versuchen.</p><p>Wenn du im Beitrag auf <strong>Schließen</strong> oder <strong>Speichern & Schließen</strong> klickst, wird er wieder freigegeben.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" Stadtrat genehmigt neues Verkehrsbudget"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Den Beitrag freigeben', '<p>Hier ist der Bearbeiter nicht zurückgekommen. Als Administrator kannst du den Beitrag entsperren: Klicke auf das Schloss.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Stadtrat genehmigt neues Verkehrsbudget"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-de'), 'Gut gemacht!', '<p>Der Beitrag ist freigegeben, und jeder mit der nötigen Berechtigung kann ihn wieder bearbeiten.</p><p>Um viele Beiträge auf einmal freizugeben, setze ihre Häkchen und wähle <strong>Aktionen</strong> › <strong>Freigeben</strong>.</p><p>Sei vorsichtig: Wenn der Bearbeiter noch am Beitrag arbeitet, können seine Änderungen verloren gehen.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
